#!/usr/bin/env bash
set -euo pipefail
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.."&&pwd)";EXP_ROOT="${EXP_ROOT:-/linxi/dataset/FGDD_v1/aircraft_ipc3_label_controls_v1}";FGDD_ROOT=/linxi/dataset/FGDD_v1/aircraft_ipc3_seed0_v1;CONTROL_ROOT=/linxi/dataset/FG_SoftAugFactorial_v2/aircraft_ipc3_v1;DATA_ROOT=/linxi/dataset/FG_SRe2L_repro/v1/datasets;TEACHER=/linxi/dataset/FG_SRe2L_standard/v1/teachers/A_imsize224/tseed42/ResNet18.pth;R0_FKD=/linxi/dataset/FG_HardAugFactorial_v2/aircraft_ipc3_v1/fkd/fullframe_cutmix/random_real/source_seed0/ipc3_bs20_ipc3;R3_FKD="$FGDD_ROOT/fkd/r3_fg_confusion_gain/ipc3_bs20_ipc3";R0_IMAGES=/linxi/dataset/FG_CoDA_standard/v2/baselines/random_real_standard/selected/A_imsize224/rseed0/ipc3;R3_IMAGES="$FGDD_ROOT/selection/selected/r3_fg_confusion_gain/ipc3";GPUS=(${GPUS:-0 1});EVALS_PER_GPU=${EVALS_PER_GPU:-4}
mkdir -p "$EXP_ROOT"/{logs,status,locks,fixed,derived_fkd,results,post_eval,summary};ts(){ date --iso-8601=seconds; };images(){ [[ $1 == r0_random ]]&&echo "$R0_IMAGES"||echo "$R3_IMAGES"; };source_fkd(){ [[ $1 == r0_random ]]&&echo "$R0_FKD"||echo "$R3_FKD"; };derived(){ echo "$EXP_ROOT/derived_fkd/$1/ipc3_bs20_ipc3"; }
prepare(){ local labels="$EXP_ROOT/fixed/fixed_t20_probabilities.pt" context="$EXP_ROOT/fixed/fixed_label_context.json" method destination;if [[ ! -f $labels || ! -f $context ]];then CUDA_VISIBLE_DEVICES=0 PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION=python python -u "$ROOT_DIR/CV-DD/fine_grained/prepare_fixed_image_soft_fkd.py" fixed --image-roots "$R0_IMAGES" "$R3_IMAGES" --teacher "$TEACHER" --labels "$labels" --context "$context" --workers 8 >"$EXP_ROOT/logs/fixed_labels.log" 2>&1;fi;for method in r0_random r3_fg_confusion_gain;do destination="$(derived "$method")";if [[ ! -f $destination/fixed_target_manifest.json ]];then python "$ROOT_DIR/CV-DD/fine_grained/prepare_fixed_image_soft_fkd.py" derive --source "$(source_fkd "$method")" --destination "$destination" --images "$(images "$method")" --labels "$labels" --context "$context">"$EXP_ROOT/logs/derive_${method}.log" 2>&1;fi;python "$ROOT_DIR/CV-DD/fine_grained/audit_fkd.py" --fkd-dir "$destination" --images 300 --classes 100 --batch-size 20 --epochs 400 --output "$destination/fkd_audit.json">>"$EXP_ROOT/logs/derive_${method}.log" 2>&1;done;}
eval_one(){ local condition method student gpu result log fkd extra=();condition=$1;method=$2;student=$3;gpu=$4;result="$EXP_ROOT/results/$condition/$method/ipc3_sseed$student.json";log="$EXP_ROOT/logs/eval_${condition}_${method}_s$student.log";mkdir -p "$(dirname "$result")";exec 7>"$result.lock";flock -n 7||return 75;if [[ $condition == hard_fullframe ]];then fkd="$(source_fkd "$method")";extra=(--fkd-hard-label --student-protocol-name standard_protocol_v2_fgdd_hard_fullframe);else fkd="$(derived "$method")";extra=(--fkd-target-probabilities --mix-type cutmix --student-protocol-name standard_protocol_v2_fgdd_fixed_image_soft);fi;if [[ ! -f $result ]];then CUDA_VISIBLE_DEVICES=$gpu PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION=python OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 python -u "$ROOT_DIR/CV-DD/validate/train_fkd.py" --model ResNet18 --ipc 3 --exp-name "fgdd_${condition}_${method}_s$student" --original-data-path "$(images "$method")" --fkd-path "$fkd" --output-dir "$EXP_ROOT/post_eval/$condition/$method/sseed$student" --batch-size 20 --epochs 400 --dataset-name A_imsize224 --gradient-accumulation-steps 2 "${extra[@]}" --workers 8 --persistent-workers --fkd_seed 42 --train-seed "$student" --temperature 20 --student-initialization imagenet-v1 --adamw-weight-decay 1e-5 --adamw-beta1 .9 --adamw-beta2 .999 --adamw-eps 1e-8 --adamw-backbone-lr 1e-4 --adamw-head-lr 1e-3 --cosine-t-max 400 --cosine-eta-min 0 --val-dir "$DATA_ROOT/A_imsize224/test" --disable-wandb --per-class-output "$result">"$log" 2>&1;fi;}
main(){ exec 9>"$EXP_ROOT/locks/launcher.lock";flock -n 9||exit 75;rm -f "$EXP_ROOT/status/launcher.failed" "$EXP_ROOT/status/launcher.complete";echo "$(ts) started new_students=12 teacher_queries=union_images_x2">"$EXP_ROOT/status/launcher.running";prepare;echo "$(ts) complete">"$EXP_ROOT/status/preparation.complete";local pids=() i=0 condition method student gpu p failed=0;for condition in hard_fullframe fixed_image_soft_cutmix;do for method in r0_random r3_fg_confusion_gain;do for student in 42 43 44;do gpu=${GPUS[$((i%2))]};eval_one "$condition" "$method" "$student" "$gpu"&pids+=("$!");i=$((i+1));if((${#pids[@]}==2*EVALS_PER_GPU));then for p in "${pids[@]}";do wait "$p"||failed=1;done;((failed==0));pids=();fi;done;done;done;for p in "${pids[@]}";do wait "$p"||failed=1;done;((failed==0));python "$ROOT_DIR/CV-DD/fine_grained/summarize_fgdd_v1_label_controls.py" --root "$EXP_ROOT" --fgdd-root "$FGDD_ROOT" --control-root "$CONTROL_ROOT">"$EXP_ROOT/logs/summary.log" 2>&1;rm -f "$EXP_ROOT/status/launcher.running";echo "$(ts) complete">"$EXP_ROOT/status/launcher.complete";}
trap 'r=$?;if((r));then rm -f "$EXP_ROOT/status/launcher.running";echo "$(ts) exit=$r">"$EXP_ROOT/status/launcher.failed";fi' EXIT
main
